import {missionRows,normalizeMissions} from './missions.js';
import {DRAFT_BONUS} from './slipstream.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
export function renderMissions(body,profile,state){const book=normalizeMissions(profile.missions),intro=el('div','mission-intro');intro.append(el('strong','',book.completed+' completed · ◉ '+book.earned+' earned'),el('p','',state?'Finish this race to bank progress and bonus coins.':'Progress carries across finished races. New missions replace paid ones on your next race.'));body.append(intro);const grid=el('div','mission-grid');for(const row of missionRows(profile,state)){const card=el('article','mission-card'+(row.paid?' paid':'')),head=el('div','mission-card-head');head.append(el('span','',row.paid?'✓':'◎'),el('h3','',row.name),el('b','','◉ '+row.reward));const progress=el('div','mission-progress'),fill=el('span','');fill.style.width=Math.min(100,row.current/row.target*100)+'%';progress.append(fill);progress.setAttribute('role','progressbar');progress.setAttribute('aria-label',row.name);progress.setAttribute('aria-valuemin','0');progress.setAttribute('aria-valuemax',row.target);progress.setAttribute('aria-valuenow',Math.floor(row.current*10)/10);const value=row.unit?row.current.toFixed(1):Math.floor(row.current),status=row.paid?'Paid · Next mission next race':row.current>=row.target?'Ready · Finish to bank':value+'/'+row.target+(row.unit?' '+row.unit:'')+(row.current>row.banked?' · This run':'');card.append(head,el('p','',row.description),progress,el('small','',status));grid.append(card);}body.append(grid);}
export function createRaceExtras($,profile){let last=-Infinity,lastRun=null;return {update(s){const race=s.gameMode==='race'&&s.mode!=='ready',charge=s.slipstream||0;$('mission-hud').hidden=!race;$('draft-hud').hidden=!race||charge<.005;document.querySelector('.game').classList.toggle('drafting',race&&charge>.01);if(charge>.005){$('draft-label').textContent=s.drafting?'DRAFT': 'OVERTAKE';$('draft-value').textContent=s.nitroTime>0||s.boostTime>0?'STORED':'+'+Math.round(charge*DRAFT_BONUS)+' KM/H';$('draft-fill').style.width=charge*100+'%';$('draft-hud').classList.toggle('full',charge>.98);}const runId=profile().active?.id||'';if(runId!==lastRun||s.time-last>.15||s.time<last||last===-Infinity){const rows=missionRows(profile(),profile().active?.mode==='race'&&race?s:null);$('mission-count').textContent=rows.filter(m=>m.paid||m.current>=m.target).length+'/3';last=s.time;lastRun=runId;}const canvas=$('road');canvas.dataset.slipstream=charge.toFixed(3);canvas.dataset.drafting=String(!!s.drafting);canvas.dataset.draftSeconds=(s.draftSeconds||0).toFixed(2);}};}
